def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not provide interface {iface}")

    required_methods = set(iface.names(all=True))
    candidate_methods = set(dir(candidate))

    missing_methods = required_methods - candidate_methods
    if missing_methods:
        errors.extend(f"Missing method: {method}" for method in missing_methods)

    for name in required_methods:
        if name in candidate_methods:
            try:
                iface_method_signature = signature(getattr(iface, name))
                candidate_method_signature = signature(getattr(candidate, name))
                if iface_method_signature!= candidate_method_signature:
                    errors.append(f"Incorrect signature for method {name}: expected {iface_method_signature}, got {candidate_method_signature}")
            except TypeError:
                continue

    required_attributes = set(attr for attr in iface.names(all=True) if not callable(getattr(iface, attr)))
    candidate_attributes = set(attr for attr in dir(candidate) if not callable(getattr(candidate, attr)))

    missing_attributes = required_attributes - candidate_attributes
    if missing_attributes:
        errors.extend(f"Missing attribute: {attr}" for attr in missing_attributes)

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

