import inspect
def verifyObject(iface, candidate, tentative=False):
    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not provide interface {iface}")

    required_methods = set(iface.names(all=True))
    candidate_methods = set(dir(candidate))

    missing_methods = required_methods - candidate_methods
    for method_name in missing_methods:
        errors.append(f"Missing method: {method_name}")

    for method_name in required_methods.intersection(candidate_methods):
        required_sig = inspect.signature(getattr(iface, method_name))
        candidate_method = getattr(candidate, method_name)
        if not callable(candidate_method):
            errors.append(f"Not callable: {method_name}")
            continue
        candidate_sig = inspect.signature(candidate_method)
        if required_sig!= candidate_sig:
            errors.append(f"Incorrect signature for {method_name}: expected {required_sig}, got {candidate_sig}")

    required_attributes = {name for name, value in iface.namesAndDescriptions(all=True) if not callable(value)}
    candidate_attributes = {name for name in dir(candidate) if not callable(getattr(candidate, name))}

    missing_attributes = required_attributes - candidate_attributes
    for attr_name in missing_attributes:
        errors.append(f"Missing attribute: {attr_name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

