def cachedmethod(cache, key=hash, lock=None):
    def decorator(method):
        def wrapper(self, *args, **kwargs):
            k = key(*args, **kwargs)
            if k in cache:
                return cache[k]
            if lock:
                with lock:
                    if k not in cache:
                        cache[k] = method(self, *args, **kwargs)
            else:
                cache[k] = method(self, *args, **kwargs)
            return cache[k]
        return wrapper
    return decorator

