def mru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = OrderedDict()
        def wrapper(*args, **kwargs):
            key = (args, kwargs) if not typed else (args, kwargs, type(args), type(kwargs))
            if key in cache:
                return cache.move_to_end(key, last=True)[1]
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                cache.popitem(last=False)
            cache[key] = result
            return result
        return wrapper
    return decorator

