            while order and order[0][1] <= now - ttl:
                del cache[order.pop(0)[0]]

            if key in cache:
                result, expiry = cache[key]
                if expiry > now:
                    return result
                else:
                    del cache[key]
                    order.remove(key)

            result = func(*args, **kwargs)
            cache[key] = (result, now + ttl)
            order.append((key, now))

            if len(cache) > maxsize:
                oldest_key, _ = order.pop(0)
                del cache[oldest_key]

            return result

        wrapper.cache_clear = cache.clear
        wrapper.cache_info = lambda: (len(cache), maxsize, len(order), len(order) - len(cache))
        return wrapper

    return decorator

def cached(cache, key=hash, lock=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(args, kwargs)
            if k in cache:
                return cache[k]
            if lock:
                with lock:
                    if k not in cache:
                        cache[k] = func(*args, **kwargs)
            else:
                cache[k] = func(*args, **kwargs)
            return cache[k]
        return wrapper
    return decorator

