from rdflib import Graph, Node, URIRef
def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set[Node]] = None) -> Set[Node]:
    if roots is None:
        roots = set()
    children = {s for s, p, o in graph.triples((None, prop, None))}
    parents = {o for s, p, o in graph.triples((None, prop, None))}
    potential_roots = parents - children
    roots.update(potential_roots)
    for root in potential_roots:
        find_roots(graph, prop, roots)
    return roots

